svg.script:

window.addEventListener('DOMContentLoaded', () => {
  const boardGroup = document.getElementById('boardGroup');
  const piecesGroup = document.getElementById('piecesGroup');
  const scoreEl = document.getElementById('scoreEl');
  const highScoreEl = document.getElementById('highScoreEl');

  let highScore = localStorage.getItem('eagle_blocks_high') || 0;
  highScoreEl.textContent = `BEST: ${highScore}`;

  const GRID_SIZE = 8;
  const CELL_SIZE = 40;
  const BOARD = Array(GRID_SIZE).fill(null).map(() => Array(GRID_SIZE).fill(null));
  const BLOCK_COLORS = ['#facc15', '#ffffff', '#eab308', '#fef08a']; // Yellow, White, Gold

  let score = 0;

  // Draw 8x8 Board
  for (let r = 0; r < GRID_SIZE; r++) {
    for (let c = 0; c < GRID_SIZE; c++) {
      const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
      rect.setAttribute('x', c * CELL_SIZE);
      rect.setAttribute('y', r * CELL_SIZE);
      rect.setAttribute('width', CELL_SIZE - 2);
      rect.setAttribute('height', CELL_SIZE - 2);
      rect.setAttribute('class', 'grid-cell');
      rect.setAttribute('id', `cell_${r}_${c}`);
      boardGroup.appendChild(rect);
    }
  }

  const SHAPES = [
    [[1,1],[1,1]], // 2x2 Square
    [[1,1,1]],     // 3-line horizontal
    [[1],[1],[1]], // 3-line vertical
    [[1,0],[1,1]], // L-shape
    [[1]],         // Single dot
    [[1,1],[0,1]]  // Corner shape
  ];

  function spawnPieces() {
    piecesGroup.innerHTML = '';
    for (let i = 0; i < 3; i++) {
      const shape = SHAPES[Math.floor(Math.random() * SHAPES.length)];
      const color = BLOCK_COLORS[Math.floor(Math.random() * BLOCK_COLORS.length)];
      createPiece(shape, color, 120 + i * 220, 0);
    }
  }

  function createPiece(shape, color, x, y) {
    const pGroup = document.createElementNS('http://www.w3.org/2000/svg', 'g');
    pGroup.setAttribute('transform', `translate(${x}, ${y})`);
    pGroup.setAttribute('cursor', 'pointer');

    shape.forEach((row, r) => {
      row.forEach((cell, c) => {
        if (cell) {
          const b = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
          b.setAttribute('x', c * 24);
          b.setAttribute('y', r * 24);
          b.setAttribute('width', 22);
          b.setAttribute('height', 22);
          b.setAttribute('fill', color);
          b.setAttribute('rx', 4);
          pGroup.appendChild(b);
        }
      });
    });

    piecesGroup.appendChild(pGroup);
  }

  spawnPieces();

  // Escape key redirect
  window.addEventListener('keydown', (e) => {
    if (e.key === "'") window.location.href = "https://www.google.com";
  });
});
